// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Set up program operator
        vm.prank(caller);
        // Cannot call addProgramOperator - not in interface, so we need to use the modifier
        // Actually the only way to become operator is through initialization or other means
        // But the test only cares about transferOwnership behavior, not create
        // Let's test the property directly on transferOwnership

        // Initialize the contract
        c.initialize();

        // Transfer ownership to caller so they can call transferOwnership as owner
        vm.prank(address(c));
        // Cannot directly set owner - use transferOwnership from current owner
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.transferOwnership(caller);

        // Now caller is owner, test transferOwnership with non-zero newOwner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // The reference P: require(newOwner != address(0)) -> should succeed
        // The buggy M: require(newOwner == address(0)) -> should revert
        // So the general rule: with non-zero newOwner, transferOwnership should succeed
        assertTrue(success, "transferOwnership should succeed for non-zero newOwner");
    }
}

